        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleFullscreen"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg v-if="uiState.isFullscreen" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"></path>
        </svg>
        <svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"></path>
        </svg>
      </div>
    </div>

    <!-- Toast 提示 -->
    <Transition name="toast">
      <div v-if="uiState.showToast" class="toast">
        {{ uiState.toastMessage }}
      </div>
    </Transition>

    <!-- 当前所在模块信息浮层 -->
    <Transition name="module-info">
      <div v-if="currentModuleInfo" class="module-location-panel">
        <div class="module-location-name" :style="{ color: currentModuleInfo.color }">
          📍 {{ currentModuleInfo.moduleName }}
        </div>
        <div class="module-location-status">
          <span v-if="moduleLoading">⏳ 地块加载中...</span>
          <span v-else-if="currentModuleInfo.isLoaded">✅ 当前地块已加载</span>
          <span v-else>📦 当前地块未加载</span>
        </div>
        <button
          v-show="!moduleLoading"
          class="module-location-btn"
          :class="{ loaded: currentModuleInfo.isLoaded }"
          @click.stop="onModuleLocationAction"
          @touchstart.prevent.stop
          @touchend.prevent.stop="onModuleLocationAction"
        >
          <span v-if="currentModuleInfo.isLoaded">点击卸载</span>
          <span v-else>点击加载</span>
        </button>
        <!-- 加载中时占位，保持按钮区域不收缩 -->
        <div v-show="moduleLoading" class="module-location-btn-placeholder"></div>
      </div>
    </Transition>

    <!-- Debug面板 -->
    <DebugScenePanel
      ref="debugScenePanelRef"
      :debug-manager="debugManager"
      :npc-manager="npcManager"
      :scene-manager="sceneManager"
      :camera-sensitivity="cameraSensitivity"
:initial-config="initialDebugConfig"
      @config-change="onDebugConfigChange"
      @log-debug-info="onLogDebugInfo"
      @reset-physics="onResetPhysics"
      @module-toggle="onModuleToggle"
    />

    <!-- 交互对话框 -->
    <InteractionDialog ref="interactionRef" />
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from 'vue';
import VirtualJoystick from '../../components/VirtualJoystick.vue';
import DebugScenePanel from '../../components/DebugScenePanel.vue';
import InteractionDialog from '../../components/InteractionDialog.vue';
import { ViewerSDK, DialogType, CLIFF_DETECTION_CONFIG } from '@tencent/viewer-sdk';
import type { ModuleLocationInfo } from '@tencent/viewer-sdk';

// DOM 引用
const containerRef = ref<HTMLDivElement>();
const virtualJoystickRef = ref<InstanceType<typeof VirtualJoystick>>();
const debugScenePanelRef = ref<InstanceType<typeof DebugScenePanel>>();
const interactionRef = ref<DialogType>();

// viewerSDK 实例
const viewerSDK = new ViewerSDK();

// 用于触发 Vue 响应式更新的状态
const pluginUIState = ref<{
  isOrbitControlActive: boolean;
  isOrbitControlManuallyActivated: boolean;
  isFullscreen: boolean;
  showToast: boolean;
  toastMessage: string;
  currentModelId: string;
  selectedModelId: string;
  isJumping: boolean;
  isSceneReady: boolean;
}>({
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
  isFullscreen: false,
  showToast: false,
  toastMessage: '',
  currentModelId: '',
  selectedModelId: '',
  isJumping: false,
  isSceneReady: false,
});

// 从 viewerSDK 获取的响应式状态
const uiState = computed(() => ({
  ...pluginUIState.value,
}));

// 当前所在模块信息
const currentModuleInfo = ref<ModuleLocationInfo | null>(null);
const moduleLoading = ref(false);

// 用于标记 onModuleToggle 中的加载操作是否已被取消（浮层触发加载时会递增此版本号）
let moduleToggleVersion = 0;

// 初始调试配置（模板和场景就绪后共用，避免硬编码重复）
const initialDebugConfig = { showColliders: true, showGaussianBounds: true };

// 摄像机灵敏度（用于 DebugPanel）
const pluginCameraSensitivity = ref(0.003);
const cameraSensitivity = computed(() => pluginCameraSensitivity.value);

// 标记 viewerSDK 是否已初始化（用于触发 computed 重新计算）
const isPluginInitialized = ref(false);

// 获取 Debug 管理器（用于 DebugPanel）
const debugManager = computed(() => {
  if (!isPluginInitialized.value) return undefined;
  return viewerSDK?.getDebugManager();
});

// 获取 NPC 管理器（用于 DebugPanel）
const npcManager = computed(() => {
  if (!isPluginInitialized.value) return undefined;
  return viewerSDK?.getNPCManager();
});

// 获取 Scene 管理器（用于 DebugPanel）
const sceneManager = computed(() => {
  if (!isPluginInitialized.value) return undefined;
  return viewerSDK?.getSceneManager();
});

onMounted(async () => {
  if (!containerRef.value) return;

  // 解析 URL 参数
  const urlParams = viewerSDK.parseURLParams('/debug-viewer');

  await viewerSDK.init({
    container: containerRef.value,
    sceneUrl: urlParams.sceneUrl,
    defaultOperationMode: 'dual',
    enableCliffDetection: true,
    cliffDetectionMode: 'slide',
    cliffDetectionConfig: {
      enabled: CLIFF_DETECTION_CONFIG.ENABLED,
      checkDistance: CLIFF_DETECTION_CONFIG.CHECK_DISTANCE,
      maxFallDistance: CLIFF_DETECTION_CONFIG.MAX_FALL_DISTANCE,
      safetyMargin: CLIFF_DETECTION_CONFIG.SAFETY_MARGIN,
    },
    interactionRef: interactionRef.value!,
    gaussianAutoLoad: false, // 禁用高斯泼溅自动加载，改为手动点击模块列表加载
  });

  // 监听 viewerSDK 状态变化
  viewerSDK.onUIStateChange((newState) => {
    Object.assign(pluginUIState.value, newState);

    // 场景就绪后，从 sceneManager 中获取模块列表并传给 DebugScenePanel
    if (newState.isSceneReady) {
      const gsManager = viewerSDK.getSceneManager()?.getGaussianSplattingManager();
      const modules = gsManager?.getModules() || [];
      if (modules.length > 0) {
        debugScenePanelRef.value?.setRegionModules(modules);
      }

      // 场景就绪后，重新应用初始调试配置
      // （初始化阶段场景尚未加载完毕，showColliders / showGaussianBounds 等无法生效）
      viewerSDK.updateDebugConfig(initialDebugConfig);

      // 注册模块位置变化回调，当人物进入/离开某个模块时更新 UI
      gsManager?.onModuleLocationChange((info) => {
          currentModuleInfo.value = info;
          // 当切换模块时重置加载状态
          moduleLoading.value = false;
        });
      }
  });

  viewerSDK.onCameraSensitivityChange((newValue) => {
    pluginCameraSensitivity.value = newValue;
  });

  // 初始化状态同步
  Object.assign(pluginUIState.value, viewerSDK.uiState);
  pluginCameraSensitivity.value = viewerSDK.cameraSensitivity;

  isPluginInitialized.value = true;


  // 设置外部组件回调
  viewerSDK.setKeyboardEdgeArcCallback((direction, fadeOut) => {
    if (virtualJoystickRef.value) {
      virtualJoystickRef.value.showEdgeArcFromKeyboard(direction, fadeOut);
    }
  });

  viewerSDK.setEdgeArcFadeOutCallback(() => {
    if (virtualJoystickRef.value) {
      virtualJoystickRef.value.startEdgeArcFadeOut();
    }
  });

  // 设置输入重置回调（页面失焦/切换窗口时重置摇杆）
  viewerSDK.setInputResetCallback(() => {
    if (virtualJoystickRef.value) {
      virtualJoystickRef.value.forceReset();
    }
  });

  // 开始动画循环
  viewerSDK.animate();
});

onUnmounted(() => {
  viewerSDK?.dispose();
});

// ==================== 事件处理方法 ====================

function onJoystickMove(data: { x: number; y: number; distance: number; edgeRatio?: number }) {
  viewerSDK?.updateJoystick(data);
}

function onTouchDelta(delta: { x: number; y: number }) {
  viewerSDK?.updateTouchDelta(delta);
}

function onCameraRotate(rotation: number) {
  viewerSDK?.updateCameraRotation(rotation);
}

function onCameraRotationSpeed(speed: number) {
  viewerSDK?.updateCameraRotationSpeed(speed);
}

function onOperationModeChange(mode: 'auto' | 'single' | 'dual') {
  viewerSDK?.setOperationMode(mode);
}

function onRunToggle(isRunning: boolean) {
  viewerSDK?.toggleRun(isRunning);
}

// 跳跃按钮事件处理
function onJumpStart() {
  viewerSDK?.setJumpPressed(true);
}

function onJumpEnd() {
  viewerSDK?.setJumpPressed(false);
}

// 圈形按钮事件处理
function onOrbitButtonStart() {
  viewerSDK?.setAutoRotate(true);
}

function onOrbitButtonEnd() {
  viewerSDK?.setAutoRotate(false);
}

async function toggleFullscreen() {
  await viewerSDK?.toggleFullscreen();
}

// ==================== Debug 事件处理方法 ====================

function onDebugConfigChange(config: any) {
  viewerSDK?.updateDebugConfig(config);
}

function onLogDebugInfo() {
  viewerSDK?.logDebugInfo();
}

function onResetPhysics() {
  viewerSDK?.resetPhysics();
}

/**
 * 当前所在模块的加载/卸载操作
 * 加载时会先取消左侧面板正在加载的模块，再卸载所有其他已加载的模块，只展示当前要加载的模块
 */
async function onModuleLocationAction() {
  if (!currentModuleInfo.value || moduleLoading.value) return;

  const { moduleName, isLoaded } = currentModuleInfo.value;
  const gsManager = viewerSDK.getSceneManager()?.getGaussianSplattingManager();

  if (isLoaded) {
    // 卸载当前模块
    gsManager?.manualUnloadModule(moduleName);
    // 手动刷新当前模块状态
    currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: false };
    // 同步 DebugScenePanel 面板中的模块加载状态
    debugScenePanelRef.value?.onModuleUnloaded?.(moduleName);
  } else {
    // 递增版本号，使 onModuleToggle 中正在进行的异步加载完成后不再更新状态
    moduleToggleVersion++;

    // 先取消左侧面板中正在加载的模块
    const loadingModuleNames = debugScenePanelRef.value?.getLoadingModules?.() || [];
    for (const loadingName of loadingModuleNames) {
      if (loadingName !== moduleName) {
        gsManager?.manualUnloadModule(loadingName);
        debugScenePanelRef.value?.onModuleUnloaded?.(loadingName);
      }
    }

    // 再卸载所有其他已加载的模块
    const allModules = gsManager?.getModules() || [];
    for (const mod of allModules) {
      if (mod.name !== moduleName && gsManager?.isModuleLoaded(mod.name)) {
        gsManager.manualUnloadModule(mod.name);
        debugScenePanelRef.value?.onModuleUnloaded?.(mod.name);
      }
    }

    // 加载当前模块
    moduleLoading.value = true;
    try {
      await gsManager?.manualLoadModule(moduleName);
      currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: true };
      debugScenePanelRef.value?.onModuleLoaded(moduleName);
    } catch (error) {
      console.error(`加载模块 ${moduleName} 失败:`, error);
      debugScenePanelRef.value?.onModuleLoadFailed(moduleName);
    } finally {
      moduleLoading.value = false;
    }
  }
}

/**
 * 模块点击事件处理：手动加载/卸载高斯泼溅模块
 */
async function onModuleToggle(moduleName: string, shouldLoad: boolean) {
  const gsManager = viewerSDK.getSceneManager()?.getGaussianSplattingManager();
  if (shouldLoad) {
    // 记录当前版本号，用于加载完成后判断是否已被浮层操作取消
    const versionAtStart = moduleToggleVersion;
    try {
      await gsManager?.manualLoadModule(moduleName);
      // 如果版本号已变化，说明加载期间浮层触发了新的加载操作，当前结果应被忽略
      if (versionAtStart !== moduleToggleVersion) {
        console.log(`模块 ${moduleName} 的面板加载已被浮层操作取消，忽略回调`);
        return;
      }
      debugScenePanelRef.value?.onModuleLoaded(moduleName);
      // 同步更新当前所在模块信息浮层的加载状态
      if (currentModuleInfo.value && currentModuleInfo.value.moduleName === moduleName) {
        currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: true };
      }
    } catch (error) {
      // 如果版本号已变化，说明是被取消导致的错误，静默忽略
      if (versionAtStart !== moduleToggleVersion) {
        console.log(`模块 ${moduleName} 的面板加载已被浮层操作取消，忽略错误`);
        return;
      }
      console.error(`加载模块 ${moduleName} 失败:`, error);
      debugScenePanelRef.value?.onModuleLoadFailed(moduleName);
    }
  } else {
    gsManager?.manualUnloadModule(moduleName);
    // 同步更新当前所在模块信息浮层的加载状态
    if (currentModuleInfo.value && currentModuleInfo.value.moduleName === moduleName) {
      currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: false };
    }
  }
}
</script>

